export const courses: Course[] = raw.map(course => ({
  ...course,
  cover: `/courses/${course.slug}.webp`,
  outcome: defaultOutcome,
}));

export const totalLearningHours = courses.reduce((total, course) => total + course.hours, 0);
export const totalModules = courses.reduce((total, course) => total + course.modules.length, 0);

export function getCourse(slug: string) {
  return courses.find(course => course.slug === slug);
}

export function getCourseTitle(slug: string) {
  return getCourse(slug)?.title || slug;
}

export function coursesByCategory(category: CourseCategory | 'All') {
  return category === 'All' ? courses : courses.filter(course => course.category === category);
}
